package com.example.demo.modules.board.entity;import jakarta.persistence.*;import lombok.*;import java.time.LocalDateTime;@Entity @Table(name="team_posts") @Data @NoArgsConstructor public class TeamPost{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=100)private String title;@Column(nullable=false,length=80)private String gameName;private String activityType;private LocalDateTime startTime;private LocalDateTime endTime;private Integer maxPlayers;private Integer currentPlayers=1;private Boolean voiceRequired=false;private String rankRequirement;@Lob private String description;private String tags;@Enumerated(EnumType.STRING)private PostStatus status=PostStatus.RECRUITING;@ManyToOne(fetch=FetchType.EAGER)@JoinColumn(name="member_id")private Member captain;private LocalDateTime createdAt;@PrePersist void create(){createdAt=LocalDateTime.now();}}
